"428 :     public Partial with(DateTimeFieldType fieldType, int value) {
429 :         if (fieldType == null) {
430 :             throw new IllegalArgumentException("The field type must not be null");
431 :         }
432 :         int index = indexOf(fieldType);
433 :         if (index == -1) {
434 :             DateTimeFieldType[] newTypes = new DateTimeFieldType[iTypes.length + 1];
435 :             int[] newValues = new int[newTypes.length];
436 :             
437 :             // find correct insertion point to keep largest-smallest order
438 :             int i = 0;
439 :             DurationField unitField = fieldType.getDurationType().getField(iChronology);
440 :             if (unitField.isSupported()) {
441 :                 for (; i < iTypes.length; i++) {
442 :                     DateTimeFieldType loopType = iTypes[i];
443 :                     DurationField loopUnitField = loopType.getDurationType().getField(iChronology);
444 :                     if (loopUnitField.isSupported()) {
445 :                         int compare = unitField.compareTo(loopUnitField);
446 :                         if (compare > 0) {
447 :                             break;
448 :                         } else if (compare == 0) {
449 :                             DurationField rangeField = fieldType.getRangeDurationType().getField(iChronology);
450 :                             DurationField loopRangeField = loopType.getRangeDurationType().getField(iChronology);
451 :                             if (rangeField.compareTo(loopRangeField) > 0) {
452 :                                 break;
453 :                             }
454 :                         }
455 :                     }
456 :                 }
457 :             }
458 :             System.arraycopy(iTypes, 0, newTypes, 0, i);
459 :             System.arraycopy(iValues, 0, newValues, 0, i);
460 :             newTypes[i] = fieldType;
461 :             newValues[i] = value;
462 :             System.arraycopy(iTypes, i, newTypes, i + 1, newTypes.length - i - 1);
463 :             System.arraycopy(iValues, i, newValues, i + 1, newValues.length - i - 1);
464 :             // use public constructor to ensure full validation
465 :             // this isn't overly efficient, but is safe
466 :             Partial newPartial = new Partial(newTypes, newValues, iChronology);
467 :             iChronology.validate(newPartial, newValues);
468 :             return newPartial;
469 :         }
470 :         if (value == getValue(index)) {
471 :             return this;
472 :         }
473 :         int[] newValues = getValues();
474 :         newValues = getField(index).set(this, index, newValues, value);
475 :         return new Partial(this, newValues);
476 :     }"

"189 :     public Partial(DateTimeFieldType[] types, int[] values, Chronology chronology) {
190 :         super();
191 :         chronology = DateTimeUtils.getChronology(chronology).withUTC();
192 :         iChronology = chronology;
193 :         if (types == null) {
194 :             throw new IllegalArgumentException("Types array must not be null");
195 :         }
196 :         if (values == null) {
197 :             throw new IllegalArgumentException("Values array must not be null");
198 :         }
199 :         if (values.length != types.length) {
200 :             throw new IllegalArgumentException("Values array must be the same length as the types array");
201 :         }
202 :         if (types.length == 0) {
203 :             iTypes = types;
204 :             iValues = values;
205 :             return;
206 :         }
207 :         for (int i = 0; i < types.length; i++) {
208 :             if (types[i] == null) {
209 :                 throw new IllegalArgumentException("Types array must not contain null: index " + i);
210 :             }
211 :         }
212 :         DurationField lastUnitField = null;
213 :         for (int i = 0; i < types.length; i++) {
214 :             DateTimeFieldType loopType = types[i];
215 :             DurationField loopUnitField = loopType.getDurationType().getField(iChronology);
216 :             if (i > 0) {
217 :                 int compare = lastUnitField.compareTo(loopUnitField);
218 :                 if (compare < 0 || (compare != 0 && loopUnitField.isSupported() == false)) {
219 :                     throw new IllegalArgumentException("Types array must be in order largest-smallest: " +
220 :                             types[i - 1].getName() + " < " + loopType.getName());
221 :                 } else if (compare == 0) {
222 :                     if (types[i - 1].getRangeDurationType() == null) {
223 :                         if (loopType.getRangeDurationType() == null) {
224 :                             throw new IllegalArgumentException("Types array must not contain duplicate: " +
225 :                                             types[i - 1].getName() + " and " + loopType.getName());
226 :                         }
227 :                     } else {
228 :                         if (loopType.getRangeDurationType() == null) {
229 :                             throw new IllegalArgumentException("Types array must be in order largest-smallest: " +
230 :                                     types[i - 1].getName() + " < " + loopType.getName());
231 :                         }
232 :                         DurationField lastRangeField = types[i - 1].getRangeDurationType().getField(iChronology);
233 :                         DurationField loopRangeField = loopType.getRangeDurationType().getField(iChronology);
234 :                         if (lastRangeField.compareTo(loopRangeField) < 0) {
235 :                             throw new IllegalArgumentException("Types array must be in order largest-smallest: " +
236 :                                     types[i - 1].getName() + " < " + loopType.getName());
237 :                         }
238 :                         if (lastRangeField.compareTo(loopRangeField) == 0) {
239 :                             throw new IllegalArgumentException("Types array must not contain duplicate: " +
240 :                                             types[i - 1].getName() + " and " + loopType.getName());
241 :                         }
242 :                     }
243 :                 }
244 :             }
245 :             lastUnitField = loopUnitField;
246 :         }
247 :         
248 :         iTypes = (DateTimeFieldType[]) types.clone();
249 :         chronology.validate(this, values);
250 :         iValues = (int[]) values.clone();
251 :     }"

